    .replace(/{{\s*today\s*}}/gi, dateStr(new Date()))
    // Namespaced tokens (GHL-style) added alongside the original flat ones
    // above — both resolve the same underlying data, so every automation/
    // template saved before this addition keeps working untouched.
    .replace(/{{\s*contact\.id\s*}}/gi, row.contact_id != null ? String(row.contact_id) : '')
    .replace(/{{\s*contact\.first_name\s*}}/gi, toTitleCase(row.first_name))
    .replace(/{{\s*contact\.last_name\s*}}/gi, toTitleCase(row.last_name))
    .replace(/{{\s*contact\.full_name\s*}}/gi, toTitleCase(`${row.first_name || ''} ${row.last_name || ''}`.trim()))
    .replace(/{{\s*contact\.email\s*}}/gi, row.email || '')
    .replace(/{{\s*contact\.phone\s*}}/gi, row.phone || '')
    .replace(/{{\s*contact\.city\s*}}/gi, row.contact_city || '')
    .replace(/{{\s*contact\.state\s*}}/gi, row.contact_state || '')
    .replace(/{{\s*contact\.postal_code\s*}}/gi, row.contact_zip_code || '')
    .replace(/{{\s*contact\.country\s*}}/gi, row.contact_country || '')
    .replace(/{{\s*contact\.date_of_birth\s*}}/gi, dateStr(row.contact_birthdate))
    .replace(/{{\s*contact\.source\s*}}/gi, row.contact_lead_source || '')
    .replace(/{{\s*contact\.tags\s*}}/gi, Array.isArray(row.tags) ? row.tags.join(', ') : '')
    .replace(/{{\s*contact\.created_at\s*}}/gi, dateStr(row.contact_created_at))
    .replace(/{{\s*contact\.updated_at\s*}}/gi, dateStr(row.contact_updated_at))
    .replace(/{{\s*company\.id\s*}}/gi, row.company_id != null ? String(row.company_id) : '')
    .replace(/{{\s*company\.name\s*}}/gi, row.company_name || '')
    .replace(/{{\s*company\.phone\s*}}/gi, row.company_phone || '')
    .replace(/{{\s*company\.website\s*}}/gi, row.company_website || '')
    .replace(/{{\s*company\.address\s*}}/gi, row.company_street_address || '')
    .replace(/{{\s*company\.city\s*}}/gi, row.company_city || '')
    .replace(/{{\s*company\.state\s*}}/gi, row.company_state || '')
    .replace(/{{\s*company\.postal_code\s*}}/gi, row.company_zip_code || '')
    .replace(/{{\s*company\.country\s*}}/gi, row.company_country || '')
    // Opportunity fields only ever come from a Pipeline (Deal) trigger's own
    // row — on any other trigger type `opp` is `{}` so these all resolve to
    // '' instead of leaking a same-named column from the wrong entity (e.g.
    // a Ticket's `row.status` under a Contact/Task trigger).
    .replace(/{{\s*opportunity\.id\s*}}/gi, opp.id != null ? String(opp.id) : '')
    .replace(/{{\s*opportunity\.name\s*}}/gi, opp.name || '')
    .replace(/{{\s*opportunity\.status\s*}}/gi, opp.status || '')
    .replace(/{{\s*opportunity\.pipeline\s*}}/gi, opp.pipeline_name || '')
    .replace(/{{\s*opportunity\.pipeline_id\s*}}/gi, opp.pipeline_id != null ? String(opp.pipeline_id) : '')
    .replace(/{{\s*opportunity\.stage\s*}}/gi, opp.stage_name || '')
    .replace(/{{\s*opportunity\.stage_id\s*}}/gi, opp.stage_id != null ? String(opp.stage_id) : '')
    .replace(/{{\s*opportunity\.value\s*}}/gi, money(opp.deal_value))
    .replace(/{{\s*opportunity\.source\s*}}/gi, opp.source || '')
    .replace(/{{\s*opportunity\.created_at\s*}}/gi, dateStr(opp.created_at))
    .replace(/{{\s*opportunity\.updated_at\s*}}/gi, dateStr(opp.updated_at))
    // Appointment reuses Task/Calendar data (`activities`) — there is no
    // separate appointments table in this schema. Only resolves on those
    // two trigger types, same guard reasoning as Opportunity above.
    .replace(/{{\s*appointment\.id\s*}}/gi, appt.id != null ? String(appt.id) : '')
    .replace(/{{\s*appointment\.title\s*}}/gi, appt.name || '')
    .replace(/{{\s*appointment\.start_time\s*}}/gi, dateTimeStr(appt.start_at || appt.due_at))
    .replace(/{{\s*appointment\.end_time\s*}}/gi, dateTimeStr(appt.end_at))
    .replace(/{{\s*appointment\.status\s*}}/gi, appt.id != null ? (appt.is_completed ? 'Completed' : 'Not completed') : '')
    .replace(/{{\s*appointment\.calendar\s*}}/gi, appt.event_type || '')
    .replace(/{{\s*appointment\.location\s*}}/gi, appt.location || '')
    .replace(/{{\s*appointment\.assigned_user\s*}}/gi, appt.id != null ? (toTitleCase(row.owner_name) || '') : '')
    .replace(/{{\s*appointment\.notes\s*}}/gi, appt.notes || '')
    // User/Sales Rep — the record's owner/assigned user, already resolved
    // for every trigger type (same owner_* columns the flat tokens use).
    .replace(/{{\s*user\.id\s*}}/gi, row.owner_user_id != null ? String(row.owner_user_id) : '')
    .replace(/{{\s*user\.full_name\s*}}/gi, toTitleCase(row.owner_name) || 'your account team')
    .replace(/{{\s*user\.email\s*}}/gi, row.owner_email || '')
    .replace(/{{\s*user\.phone\s*}}/gi, row.owner_phone || '')
    // System — always resolvable, no row data involved.
    .replace(/{{\s*system\.current_date\s*}}/gi, dateStr(new Date()))
    .replace(/{{\s*system\.current_time\s*}}/gi, new Date().toLocaleTimeString())
    .replace(/{{\s*system\.current_datetime\s*}}/gi, dateTimeStr(new Date()))
    .replace(/{{\s*system\.timestamp\s*}}/gi, new Date().toISOString())
    .replace(/{{[^{}]*}}/g, '');
}

return [{
  json: {
    automationId: meta.automationId, actionId: meta.actionId, entityType: meta.entityType, entityId: meta.entityId, branch: meta.branch,
    channelId: Number(meta.action.action_config.channel_id), senderId: meta.createdBy, text: fill(meta.action.action_config.message),
  },
}];

