const meta = $input.item.json; // {automationId, actionId, entityType, entityId, branch, action, row, createdBy}
const config = meta.action.action_config || {};

// Allowlist only — the field/table/column never come from raw user
// input, they're looked up through this map, so there's no way an
// automation's saved config can point an UPDATE at an arbitrary column.
const FIELD_MAP = {
  contact: {
    lead_status: { table: 'contacts', column: 'lead_status', valueType: 'text' },
    owner_id: { table: 'contacts', column: 'owner_id', valueType: 'int' },
  },
  company: {
    account_status: { table: 'companies', column: 'account_status', valueType: 'text' },
    account_health: { table: 'companies', column: 'account_health', valueType: 'text' },
    tier: { table: 'companies', column: 'tier', valueType: 'text' },
    owner_id: { table: 'companies', column: 'owner_id', valueType: 'int' },
  },
  pipeline: {
    status: { table: 'opportunities', column: 'status', valueType: 'text' },
    stage_id: { table: 'opportunities', column: 'stage_id', valueType: 'int', extra: ', stage_entered_at = now()' },
    priority: { table: 'opportunities', column: 'priority', valueType: 'text' },
    assigned_user: { table: 'opportunities', column: 'assigned_user', valueType: 'int' },
  },
  task: {
    is_completed: { table: 'activities', column: 'is_completed', valueType: 'boolean' },
    user_id: { table: 'activities', column: 'user_id', valueType: 'int' },
  },
  calendar: {
    is_completed: { table: 'activities', column: 'is_completed', valueType: 'boolean' },
    user_id: { table: 'activities', column: 'user_id', valueType: 'int' },
  },
  ticket: {
    status: { table: 'tickets', column: 'status', valueType: 'text' },
    priority: { table: 'tickets', column: 'priority', valueType: 'text' },
    assigned_user: { table: 'tickets', column: 'assigned_user', valueType: 'int' },
  },
};

// contacts/companies/opportunities all have updated_at; activities does not.
const UPDATED_AT_TABLES = new Set(['contacts', 'companies', 'opportunities', 'tickets']);

function fail(detail) {
  return [{ json: { automationId: meta.automationId, actionId: meta.actionId, entityType: meta.entityType, entityId: meta.entityId, branch: meta.branch, status: 'error', detail } }];
}

const spec = (FIELD_MAP[meta.entityType] || {})[config.field];
if (!spec) return fail(`Field "${config.field}" is not updatable for entity type "${meta.entityType}".`);
if (config.value === undefined || config.value === null || config.value === '') return fail('No value configured for this update.');

let castedValue = config.value;
if (spec.valueType === 'int') {
  castedValue = parseInt(config.value, 10);
  if (!Number.isInteger(castedValue)) return fail(`Value "${config.value}" is not a valid id.`);
} else if (spec.valueType === 'boolean') {
  castedValue = config.value === true || config.value === 'true';
}

// Marking a task/calendar item complete (or un-complete) via automation
// should behave the same as doing it by hand — stamp/clear completed_at.
const completedAtExtra = spec.column === 'is_completed' ? ', completed_at = CASE WHEN $1::boolean THEN now() ELSE NULL END' : '';
const updatedAtExtra = UPDATED_AT_TABLES.has(spec.table) ? ', updated_at = now()' : '';

const sqlQuery = `UPDATE ${spec.table} SET ${spec.column} = $1${completedAtExtra}${spec.extra || ''}${updatedAtExtra} WHERE id = $2 RETURNING id;`;

return [{
  json: {
    automationId: meta.automationId,
    actionId: meta.actionId,
    entityType: meta.entityType,
    entityId: meta.entityId,
    branch: meta.branch,
    status: 'ok',
    sqlQuery,
    params: [castedValue, meta.entityId],
  },
}];

// $('Build Candidate Query').item (no index) always resolves to that
// node's FIRST item regardless of which of the N automations this
// invocation is actually restoring — every automation's payload was
// silently overwritten with the first automation's, so only it ever
// got evaluated. itemMatching(index) uses n8n's pairedItem tracking
// (which Postgres nodes preserve 1:1 automatically) to resolve the
// correct original upstream item for EACH item passing through here.
return $input.all().map((_, index) => ({
  json: $('Build Candidate Query').itemMatching(index).json,
}));
